"use client";

import { toast as sonnerToast, Toaster } from "sonner";

import "./toast.css";

export const toast = {
  success(message: string) {
    return sonnerToast.success(message);
  },
} as const;

export function ToastViewport() {
  return (
    <Toaster
      closeButton
      duration={4000}
      gap={8}
      position="bottom-right"
      toastOptions={{ className: "mfd-toast" }}
      visibleToasts={3}
    />
  );
}

.mfd-toast[data-sonner-toast] {
  background: var(--mfd-color-bg-elevated);
  border: 1px solid var(--mfd-color-status-success-border);
  border-radius: var(--mfd-radius-surface);
  box-shadow: var(--mfd-elevation-overlay);
  color: var(--mfd-color-text-primary);
  font: inherit;
}

.mfd-toast [data-icon] {
  color: var(--mfd-color-status-success-text);
}

.mfd-toast [data-close-button]:focus-visible {
  outline: 2px solid var(--mfd-color-border-focus);
  outline-offset: 2px;
}
